package main

import (
	"fmt"
	"strings"
)

// Finder 是服务层声明的依赖：只要“按编号取名字”，不关心数据存在哪。
type Finder func(id int) (string, bool)

// Service 是服务层函数，依赖由参数注入，换存储实现不用改它。
func Service(find Finder, ids []int) []string {
	names := []string{}
	for _, id := range ids {
		if name, ok := find(id); ok {
			names = append(names, name)
		}
	}
	return names
}

// memoryStore 是数据层实现：返回闭包即可满足 Finder。
func memoryStore() Finder {
	data := map[int]string{1: "小明", 2: "小红"}
	return func(id int) (string, bool) {
		name, ok := data[id]
		return name, ok
	}
}

func main() {
	fmt.Println("全部命中:", strings.Join(Service(memoryStore(), []int{1, 2}), ", "))
	fmt.Println("含缺失编号:", strings.Join(Service(memoryStore(), []int{1, 3}), ", "))
}

