package main

import (
	"fmt"
	"strings"
)

// caseSpec 是一行用例：用例名 + 输入 + 期望输出。
type caseSpec struct{ name, in, want string }

// normalize 是被测函数：先去首尾空白，再统一成小写。
func normalize(text string) string { return strings.ToLower(strings.TrimSpace(text)) }

// run 是极简测试运行器：遍历用例表逐条比较，最后汇总通过数。
func run(cases []caseSpec) {
	passed := 0
	for _, c := range cases {
		got := normalize(c.in)
		if got == c.want {
			passed++
			fmt.Println("PASS", c.name)
			continue
		}
		fmt.Printf("FAIL %s: got %q want %q\n", c.name, got, c.want)
	}
	fmt.Printf("通过 %d/%d\n", passed, len(cases))
}

func main() {
	run([]caseSpec{
		{"去掉首尾空白", "  Go  ", "go"},
		{"统一小写", "ABC", "abc"},
		{"空串保持不变", "", ""},
	})
}

