package main

import "fmt"

// growCost 统计写 n 个元素的总操作数：写入算 1 次，扩容时复制的每个元素也算 1 次。
// initial 是起始容量：0 表示不预分配（翻倍扩容），n 表示一次申请够。
func growCost(n, initial int) int {
	cost, used, capacity := 0, 0, initial
	for i := 0; i < n; i++ {
		if used == capacity { // 容量用完，需要重新申请更大的底层数组
			cost += used // 旧元素要全部复制过去
			if capacity == 0 {
				capacity = 1
			} else {
				capacity *= 2
			}
		}
		cost++ // 写入新元素本身
		used++
	}
	return cost
}

func main() {
	fmt.Println("元素个数:", 100)
	fmt.Printf("不预分配: 操作 %d 次\n", growCost(100, 0))
	fmt.Printf("预分配: 操作 %d 次\n", growCost(100, 100))
	fmt.Printf("节省: %d 次操作\n", growCost(100, 0)-growCost(100, 100))
}

