package main

import "fmt"

// growCost 只模拟了「不预分配」：容量从 0 开始翻倍。
func growCost(n int) int {
	cost, used, capacity := 0, 0, 0
	for i := 0; i < n; i++ {
		if used == capacity {
			cost += used
			if capacity == 0 {
				capacity = 1
			} else {
				capacity *= 2
			}
		}
		cost++
		used++
	}
	return cost
}

func main() {
	fmt.Println("元素个数: 100")
	fmt.Printf("不预分配: 操作 %d 次\n", growCost(100))
}

