package main

import (
	"fmt"
	"strconv"
)

// parsePort 解析端口：失败时补上“解析了什么”，%w 保留底层原因。
func parsePort(text string) error {
	port, err := strconv.Atoi(text)
	if err != nil {
		return fmt.Errorf("解析端口 %q: %w", text, err)
	}
	if port < 1 || port > 65535 {
		return fmt.Errorf("端口 %d 超出范围 1-65535", port)
	}
	return nil
}

// loadConfig 只补充自己这一层的信息，再原样把错误交给调用方。
func loadConfig(raw string) error {
	if err := parsePort(raw); err != nil {
		return fmt.Errorf("加载配置失败: %w", err)
	}
	return nil
}
func main() {
	for _, raw := range []string{"8080", "abc", "70000"} {
		if err := loadConfig(raw); err != nil {
			fmt.Println("错误:", err)
		} else {
			fmt.Println("端口:", raw)
		}
	}
}

