package main

import (
	"fmt"
	"strconv"
)

// parsePort 现在把底层错误直接丢给上层：调用方不知道“是谁在解析什么”。
func parsePort(text string) (int, error) {
	return strconv.Atoi(text)
}

// loadConfig 也没有补充任何上下文。
func loadConfig(raw string) (int, error) {
	return parsePort(raw)
}

func main() {
	for _, raw := range []string{"8080", "abc", "70000"} {
		port, err := loadConfig(raw)
		if err != nil {
			fmt.Println("错误:", err)
		} else {
			fmt.Println("端口:", port)
		}
	}
}

