package main

import "fmt"

// finalPrice 计算折后价（单位：分）：名字说明返回什么，调用处不用猜。
func finalPrice(priceCents, discountPercent int) int {
	if discountPercent <= 0 {
		return priceCents
	}
	if discountPercent >= 100 {
		return 0 // 边界：100% 或更大的折扣都按 0 处理
	}
	return priceCents * (100 - discountPercent) / 100
}

// describe 只负责拼展示文案，计算交给 finalPrice：一个函数一件事。
func describe(name string, priceCents, discountPercent int) string {
	return fmt.Sprintf("%s: %d 分", name, finalPrice(priceCents, discountPercent))
}

func main() {
	fmt.Println(describe("基础课", 10000, 0))
	fmt.Println(describe("进阶课", 10000, 25))
	fmt.Println(describe("年度会员", 10000, 100))
	fmt.Println(describe("异常输入", 10000, 120))
}

