package main

import "fmt"

// 命名过于简略：fp、p、d 看不出含义，读代码的人只能靠猜。
func fp(p, d int) int {
	if d <= 0 {
		return p
	}
	return p * (100 - d) / 100
}

func main() {
	fmt.Println("基础课:", fp(10000, 0), "分")
	fmt.Println("进阶课:", fp(10000, 25), "分")
	fmt.Println("年度会员:", fp(10000, 100), "分")
}
